package com.fieldar.plotfinder.core.render

/**
 * One palette slot. [index] is the value stored in `plots.colour_index`.
 *
 * [argb] is an **Int**, not a Long, and that matters. Compose's
 * `Color(value: ULong)` overload does not take an ARGB colour - it takes the
 * already-packed 64-bit representation whose low bits are a colour-space id.
 * Handing it `0xFFFF3B30UL` compiles cleanly and then throws
 * `ArrayIndexOutOfBoundsException: length=18; index=48` from inside the
 * renderer. Keeping this an Int makes `Color(colour.argb)` resolve to the
 * ARGB constructor and leaves no wrong overload to pick.
 */
data class PlotColour(val index: Int, val name: String, val argb: Int)

/**
 * Boundary colours, shared with the web tool through palette.json.
 *
 * Stored as 0xAARRGGBB with full alpha; the renderer applies [PlotAlpha] to the
 * surface it is drawing rather than baking transparency in here.
 */
val PLOT_COLOURS: List<PlotColour> = listOf(
    PlotColour(0, "red", 0xFFFF3B30.toInt()),
    PlotColour(1, "orange", 0xFFFF9F0A.toInt()),
    PlotColour(2, "yellow", 0xFFFFD60A.toInt()),
    PlotColour(3, "cyan", 0xFF64D2FF.toInt()),
    PlotColour(4, "blue", 0xFF0A84FF.toInt()),
    PlotColour(5, "purple", 0xFFBF5AF2.toInt()),
    PlotColour(6, "pink", 0xFFFF375F.toInt()),
    PlotColour(7, "white", 0xFFF2F2F7.toInt()),
)

/** Opacity each surface is drawn at, shared with the web tool. */
object PlotAlpha {
    const val WALL_FILL = 0.28f
    const val GROUND_FILL = 0.18f
    const val RAIL = 1f
    const val OUTLINE = 0.95f
}

/**
 * One crop-health severity band.
 *
 * [argb] is an Int for the same reason [PlotColour.argb] is - see the note there.
 */
data class SeverityColour(
    val level: Int,
    val name: String,
    val label: String,
    val argb: Int,
    /** Fill opacity for this band. Rises with severity; see palette.json. */
    val fillAlpha: Float,
)

/**
 * The crop-health ramp, shared with the web map through palette.json.
 *
 * Healthy through mild and stressed to critical brown. Kept apart from
 * [PLOT_COLOURS] on purpose: that palette identifies a plot, this one grades a
 * condition, and swapping them would make a red-slot plot look like a dead one.
 */
val SEVERITY_COLOURS: List<SeverityColour> = listOf(
    SeverityColour(0, "healthy", "Healthy", 0xFF2FD44E.toInt(), 0.22f),
    SeverityColour(1, "mild", "Mild", 0xFFFFE81A.toInt(), 0.55f),
    SeverityColour(2, "stressed", "Stressed", 0xFFFF8A00.toInt(), 0.68f),
    SeverityColour(3, "critical", "Critical", 0xFFFF2118.toInt(), 0.8f),
)

/**
 * The band for a severity level, clamped rather than wrapped.
 *
 * Wrapping would turn a corrupt level 4 into "healthy", which is the one wrong
 * answer that costs something: it hides a problem instead of inventing one.
 */
fun severityColour(level: Int): SeverityColour =
    SEVERITY_COLOURS[level.coerceIn(0, SEVERITY_COLOURS.size - 1)]

/**
 * The colour for a plot. Out-of-range indices wrap rather than throw: a plot
 * that arrives with a bad slot should still be drawn, just not in the slot it
 * asked for.
 */
fun plotColour(colourIndex: Int): PlotColour =
    PLOT_COLOURS[((colourIndex % PLOT_COLOURS.size) + PLOT_COLOURS.size) % PLOT_COLOURS.size]
